import{L as a,o as e,c as n,M as l}from"./chunks/framework.emYDQvNM.js";const u=JSON.parse('{"title":"和为 K 的子数组：用前缀和统计历史状态","description":"从连续区间之和推导前缀和与哈希计数，理解为什么要先查询、后记录，并用 Java 实现线性解法。","frontmatter":{"title":"和为 K 的子数组：用前缀和统计历史状态","date":"2026-11-06T00:00:00.000Z","description":"从连续区间之和推导前缀和与哈希计数，理解为什么要先查询、后记录，并用 Java 实现线性解法。","category":"算法题解","tags":["LeetCode","Java","前缀和","哈希表"],"folder":"algorithms/highlights"},"headers":[{"level":2,"title":"题意与最直接的做法","slug":"题意与最直接的做法","link":"#题意与最直接的做法","children":[]},{"level":2,"title":"把区间和变成历史查询","slug":"把区间和变成历史查询","link":"#把区间和变成历史查询","children":[]},{"level":2,"title":"不变量与更新顺序","slug":"不变量与更新顺序","link":"#不变量与更新顺序","children":[]},{"level":2,"title":"用一组含负数的输入走一遍","slug":"用一组含负数的输入走一遍","link":"#用一组含负数的输入走一遍","children":[]},{"level":2,"title":"Java 实现","slug":"java-实现","link":"#java-实现","children":[]},{"level":2,"title":"复杂度与易错点","slug":"复杂度与易错点","link":"#复杂度与易错点","children":[]}],"relativePath":"posts/leetcode-prefix-sum.md","filePath":"posts/leetcode-prefix-sum.md"}'),o={name:"posts/leetcode-prefix-sum.md"};function t(p,s,c,r,d,i){return e(),n("div",null,[...s[0]||(s[0]=[l(`<h1 id="和为-k-的子数组用前缀和统计历史状态" tabindex="-1">和为 K 的子数组：用前缀和统计历史状态 <a class="header-anchor" href="#和为-k-的子数组用前缀和统计历史状态" aria-label="Permalink to &quot;和为 K 的子数组：用前缀和统计历史状态&quot;">​</a></h1><p>这道题让我注意到，哈希表除了回答“有没有”，还可以回答“此前出现过多少次”。把连续区间换成两个历史状态之差，原本需要枚举起点的问题，就只剩一次查询。</p><h2 id="题意与最直接的做法" tabindex="-1">题意与最直接的做法 <a class="header-anchor" href="#题意与最直接的做法" aria-label="Permalink to &quot;题意与最直接的做法&quot;">​</a></h2><p><a href="https://leetcode.cn/problems/subarray-sum-equals-k/description/" target="_blank" rel="noreferrer">LeetCode 560：和为 K 的子数组</a> 要求统计整数数组中，元素之和等于 <code>k</code> 的连续、非空区间数量。</p><p>最直接的方法是固定起点，再向右累加，每遇到一次目标和就计数。这样有 <code>O(n²)</code> 个候选区间。数组允许负数，扩大窗口时总和可能减小，缩小窗口时也可能增大，因此不能靠“和太大就移动左边界”稳定地排除答案。</p><h2 id="把区间和变成历史查询" tabindex="-1">把区间和变成历史查询 <a class="header-anchor" href="#把区间和变成历史查询" aria-label="Permalink to &quot;把区间和变成历史查询&quot;">​</a></h2><p>令 <code>prefix[j]</code> 表示前 <code>j</code> 个元素的总和，特别地 <code>prefix[0] = 0</code>。左闭右开的区间 <code>[i, j)</code> 满足：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>区间和 = prefix[j] - prefix[i]</span></span>
<span class="line"><span>区间和等于 k ⇔ prefix[i] = prefix[j] - k</span></span></code></pre></div><p>扫描到右端点 <code>j</code> 时，当前前缀和已经确定。只要知道以前有多少个前缀和等于 <code>prefix[j] - k</code>，就知道以当前位置结尾的合法区间有多少个。</p><p>这里必须保存<strong>次数</strong>。不同位置可能得到相同前缀和，它们对应不同起点，不能用集合去重。哈希表的键是前缀和，值是它在历史位置出现的次数。</p><h2 id="不变量与更新顺序" tabindex="-1">不变量与更新顺序 <a class="header-anchor" href="#不变量与更新顺序" aria-label="Permalink to &quot;不变量与更新顺序&quot;">​</a></h2><p>每轮查询之前，<code>count</code> 只包含当前元素之前的前缀和。初始化 <code>count[0] = 1</code>，表示数组开始前的空前缀，它让从下标 <code>0</code> 开始的合法区间也能被统计。</p><p>每加入一个元素，严格按三个步骤更新：</p><ol><li>累加元素，得到新的 <code>sum</code>。</li><li>把 <code>count[sum - k]</code> 加入答案。</li><li>将当前 <code>sum</code> 的出现次数加一，供后续位置使用。</li></ol><p>查询必须发生在记录当前状态之前。当 <code>k = 0</code> 时，如果先记录，就会把当前前缀与自身配对，错误地算入长度为零的区间。</p><h2 id="用一组含负数的输入走一遍" tabindex="-1">用一组含负数的输入走一遍 <a class="header-anchor" href="#用一组含负数的输入走一遍" aria-label="Permalink to &quot;用一组含负数的输入走一遍&quot;">​</a></h2><p>取 <code>nums = [1, -1, 1]</code>，<code>k = 1</code>。初始只有 <code>count = {0: 1}</code>。</p><table tabindex="0"><thead><tr><th>加入的元素</th><th>当前 sum</th><th>需要的历史和</th><th>新增区间数</th><th>累计答案</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>0</td><td>1</td><td>1</td></tr><tr><td>-1</td><td>0</td><td>-1</td><td>0</td><td>1</td></tr><tr><td>1</td><td>1</td><td>0</td><td>2</td><td>3</td></tr></tbody></table><p>最后一次查询时，前缀和 <code>0</code> 已出现两次，分别对应整个 <code>[1, -1, 1]</code> 和末尾的 <code>[1]</code>。再加上开头的 <code>[1]</code>，答案为 <code>3</code>。</p><h2 id="java-实现" tabindex="-1">Java 实现 <a class="header-anchor" href="#java-实现" aria-label="Permalink to &quot;Java 实现&quot;">​</a></h2><div class="language-java"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> java.util.HashMap;</span></span>
<span class="line"><span style="color:#D73A49;">import</span><span style="color:#24292E;"> java.util.Map;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">class</span><span style="color:#6F42C1;"> Solution</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#D73A49;">    public</span><span style="color:#D73A49;"> int</span><span style="color:#6F42C1;"> subarraySum</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">int</span><span style="color:#24292E;">[] </span><span style="color:#E36209;">nums</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">int</span><span style="color:#E36209;"> k</span><span style="color:#24292E;">) {</span></span>
<span class="line"><span style="color:#24292E;">        Map&lt;</span><span style="color:#D73A49;">Integer</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">Integer</span><span style="color:#24292E;">&gt; count </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#24292E;"> HashMap&lt;&gt;();</span></span>
<span class="line"><span style="color:#24292E;">        count.</span><span style="color:#6F42C1;">put</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">        int</span><span style="color:#24292E;"> sum </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">        int</span><span style="color:#24292E;"> answer </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">        for</span><span style="color:#24292E;"> (</span><span style="color:#D73A49;">int</span><span style="color:#24292E;"> x </span><span style="color:#D73A49;">:</span><span style="color:#24292E;"> nums) {</span></span>
<span class="line"><span style="color:#24292E;">            sum </span><span style="color:#D73A49;">+=</span><span style="color:#24292E;"> x;</span></span>
<span class="line"><span style="color:#24292E;">            answer </span><span style="color:#D73A49;">+=</span><span style="color:#24292E;"> count.</span><span style="color:#6F42C1;">getOrDefault</span><span style="color:#24292E;">(sum </span><span style="color:#D73A49;">-</span><span style="color:#24292E;"> k, </span><span style="color:#005CC5;">0</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">            count.</span><span style="color:#6F42C1;">put</span><span style="color:#24292E;">(sum, count.</span><span style="color:#6F42C1;">getOrDefault</span><span style="color:#24292E;">(sum, </span><span style="color:#005CC5;">0</span><span style="color:#24292E;">) </span><span style="color:#D73A49;">+</span><span style="color:#005CC5;"> 1</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">        }</span></span>
<span class="line"><span style="color:#D73A49;">        return</span><span style="color:#24292E;"> answer;</span></span>
<span class="line"><span style="color:#24292E;">    }</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre></div><h2 id="复杂度与易错点" tabindex="-1">复杂度与易错点 <a class="header-anchor" href="#复杂度与易错点" aria-label="Permalink to &quot;复杂度与易错点&quot;">​</a></h2><p>哈希查询和更新的平均成本为 <code>O(1)</code>，总时间为平均 <code>O(n)</code>，不同前缀和最多 <code>n + 1</code> 个，空间为 <code>O(n)</code>。在本题给定的数组长度与元素范围内，前缀和和答案都可用 Java <code>int</code> 保存；迁移到更大数据范围时，应重新检查是否需要 <code>long</code>。</p><ul><li>初始的 <code>0: 1</code> 表示空前缀，不是空子数组。</li><li>同一个前缀和需要累计次数，不能覆盖成 <code>1</code>。</li><li>先查历史，再记录当前，保证区间非空。</li><li><code>[0, 0]</code>、<code>k = 0</code> 应得到 <code>3</code>，很适合检查上述顺序。</li></ul><p>这次练习中最值得留下的是“按右端点计数”的视角：当前状态只负责查询，与所有历史起点的配对工作交给哈希表。</p><p><em>整理自个人 Hot100 练习笔记，补充 Java 实现与边界说明。</em></p>`,26)])])}const h=a(o,[["render",t]]);export{u as __pageData,h as default};
